CREATE TABLE roles (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, name VARCHAR(40) NOT NULL, description VARCHAR(255), PRIMARY KEY (id), UNIQUE KEY uk_roles_name (name)) ENGINE=InnoDB;
CREATE TABLE permissions (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, code VARCHAR(100) NOT NULL, description VARCHAR(255), PRIMARY KEY (id), UNIQUE KEY uk_permissions_code (code)) ENGINE=InnoDB;
CREATE TABLE users (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, email VARCHAR(320) NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, phone VARCHAR(30), enabled BIT NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_users_email (email), KEY idx_users_email (email)) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, PRIMARY KEY (user_id, role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id CHAR(36) NOT NULL, permission_id CHAR(36) NOT NULL, PRIMARY KEY (role_id, permission_id), CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id) REFERENCES roles(id), CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id) REFERENCES permissions(id)) ENGINE=InnoDB;
CREATE TABLE guests (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, user_id CHAR(36), full_name VARCHAR(120) NOT NULL, email VARCHAR(320), phone VARCHAR(30), date_of_birth DATE, nationality VARCHAR(80), identification_type VARCHAR(30), identification_number VARCHAR(100), address VARCHAR(500), PRIMARY KEY (id), UNIQUE KEY uk_guests_user (user_id), KEY idx_guests_email (email), KEY idx_guests_phone (phone), CONSTRAINT fk_guests_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE room_types (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, name VARCHAR(100) NOT NULL, description TEXT, capacity INT NOT NULL, base_price DECIMAL(19,2) NOT NULL, size_sqm DECIMAL(8,2), number_of_beds INT NOT NULL, bed_type VARCHAR(80), amenities JSON, PRIMARY KEY (id), UNIQUE KEY uk_room_types_name (name)) ENGINE=InnoDB;
CREATE TABLE rooms (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, version BIGINT, room_number VARCHAR(20) NOT NULL, floor INT NOT NULL, room_type_id CHAR(36) NOT NULL, occupancy_status VARCHAR(20) NOT NULL, housekeeping_status VARCHAR(20) NOT NULL, operational_status VARCHAR(30) NOT NULL, description TEXT, PRIMARY KEY (id), UNIQUE KEY uk_rooms_number (room_number), KEY idx_rooms_occupancy_status (occupancy_status), KEY idx_rooms_housekeeping_status (housekeeping_status), KEY idx_rooms_operational_status (operational_status), CONSTRAINT fk_rooms_room_type FOREIGN KEY (room_type_id) REFERENCES room_types(id)) ENGINE=InnoDB;
CREATE TABLE room_images (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, room_id CHAR(36) NOT NULL, object_key VARCHAR(512) NOT NULL, bucket_name VARCHAR(100) NOT NULL, file_name VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, file_size BIGINT NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_room_images_object_key (object_key), KEY idx_room_images_room (room_id), CONSTRAINT fk_room_images_room FOREIGN KEY (room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE reservations (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, version BIGINT, reservation_code VARCHAR(32) NOT NULL, guest_id CHAR(36) NOT NULL, check_in_date DATE NOT NULL, check_out_date DATE NOT NULL, number_of_adults INT NOT NULL, number_of_children INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL, total_amount DECIMAL(19,2) NOT NULL, special_request TEXT, PRIMARY KEY (id), UNIQUE KEY uk_reservations_code (reservation_code), KEY idx_reservations_dates_status (check_in_date, check_out_date, status), KEY idx_reservations_status (status), KEY idx_reservations_guest (guest_id), CONSTRAINT chk_reservation_dates CHECK (check_out_date > check_in_date), CONSTRAINT fk_reservations_guest FOREIGN KEY (guest_id) REFERENCES guests(id)) ENGINE=InnoDB;
CREATE TABLE reservation_rooms (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, reservation_id CHAR(36) NOT NULL, room_id CHAR(36) NOT NULL, price_per_night DECIMAL(19,2) NOT NULL, number_of_nights INT NOT NULL, subtotal DECIMAL(19,2) NOT NULL, PRIMARY KEY (id), UNIQUE KEY uk_reservation_room (reservation_id, room_id), KEY idx_reservation_rooms_room (room_id), CONSTRAINT chk_reservation_room_nights CHECK (number_of_nights > 0), CONSTRAINT fk_reservation_rooms_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(id), CONSTRAINT fk_reservation_rooms_room FOREIGN KEY (room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE stays (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, reservation_id CHAR(36) NOT NULL, guest_id CHAR(36) NOT NULL, room_id CHAR(36) NOT NULL, actual_check_in_time DATETIME(6) NOT NULL, actual_check_out_time DATETIME(6), status VARCHAR(30) NOT NULL, notes TEXT, PRIMARY KEY (id), KEY idx_stays_reservation (reservation_id), KEY idx_stays_room (room_id), CONSTRAINT fk_stays_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(id), CONSTRAINT fk_stays_guest FOREIGN KEY (guest_id) REFERENCES guests(id), CONSTRAINT fk_stays_room FOREIGN KEY (room_id) REFERENCES rooms(id)) ENGINE=InnoDB;
CREATE TABLE payments (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, version BIGINT, reservation_id CHAR(36) NOT NULL, amount DECIMAL(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, payment_method VARCHAR(30) NOT NULL, payment_status VARCHAR(20) NOT NULL, transaction_reference VARCHAR(150), paid_at DATETIME(6), PRIMARY KEY (id), KEY idx_payments_reservation (reservation_id), KEY idx_payments_transaction_reference (transaction_reference), CONSTRAINT fk_payments_reservation FOREIGN KEY (reservation_id) REFERENCES reservations(id)) ENGINE=InnoDB;
CREATE TABLE equipment (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, name VARCHAR(150) NOT NULL, category VARCHAR(100), manufacturer VARCHAR(100), model VARCHAR(100), serial_number VARCHAR(150), status VARCHAR(30) NOT NULL, purchase_date DATE, warranty_expiration_date DATE, PRIMARY KEY (id), UNIQUE KEY uk_equipment_serial_number (serial_number), KEY idx_equipment_serial_number (serial_number)) ENGINE=InnoDB;
CREATE TABLE room_equipment (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, room_id CHAR(36) NOT NULL, equipment_id CHAR(36) NOT NULL, quantity INT NOT NULL DEFAULT 1, installed_at DATETIME(6), status VARCHAR(30) NOT NULL, notes TEXT, PRIMARY KEY (id), UNIQUE KEY uk_room_equipment (room_id, equipment_id), KEY idx_room_equipment_equipment (equipment_id), CONSTRAINT chk_room_equipment_quantity CHECK (quantity > 0), CONSTRAINT fk_room_equipment_room FOREIGN KEY (room_id) REFERENCES rooms(id), CONSTRAINT fk_room_equipment_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id)) ENGINE=InnoDB;
CREATE TABLE housekeeping_tasks (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, room_id CHAR(36) NOT NULL, assigned_to_id CHAR(36), task_type VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, priority VARCHAR(20) NOT NULL, assigned_at DATETIME(6), started_at DATETIME(6), completed_at DATETIME(6), notes TEXT, PRIMARY KEY (id), KEY idx_housekeeping_tasks_status (status), KEY idx_housekeeping_tasks_room (room_id), KEY idx_housekeeping_tasks_assigned (assigned_to_id), CONSTRAINT fk_housekeeping_tasks_room FOREIGN KEY (room_id) REFERENCES rooms(id), CONSTRAINT fk_housekeeping_tasks_assigned_to FOREIGN KEY (assigned_to_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE maintenance_requests (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, version BIGINT, room_id CHAR(36), equipment_id CHAR(36), reported_by_id CHAR(36) NOT NULL, assigned_to_id CHAR(36), title VARCHAR(200) NOT NULL, description TEXT NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, reported_at DATETIME(6) NOT NULL, started_at DATETIME(6), completed_at DATETIME(6), resolution TEXT, PRIMARY KEY (id), KEY idx_maintenance_requests_status (status), KEY idx_maintenance_requests_room (room_id), KEY idx_maintenance_requests_equipment (equipment_id), CONSTRAINT chk_maintenance_target CHECK (room_id IS NOT NULL OR equipment_id IS NOT NULL), CONSTRAINT fk_maintenance_requests_room FOREIGN KEY (room_id) REFERENCES rooms(id), CONSTRAINT fk_maintenance_requests_equipment FOREIGN KEY (equipment_id) REFERENCES equipment(id), CONSTRAINT fk_maintenance_requests_reported_by FOREIGN KEY (reported_by_id) REFERENCES users(id), CONSTRAINT fk_maintenance_requests_assigned_to FOREIGN KEY (assigned_to_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notifications (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, user_id CHAR(36) NOT NULL, type VARCHAR(80) NOT NULL, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL, read_at DATETIME(6), PRIMARY KEY (id), KEY idx_notifications_user_status (user_id, status), CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, user_id CHAR(36), action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(36) NOT NULL, old_value JSON, new_value JSON, ip_address VARCHAR(45), PRIMARY KEY (id), KEY idx_audit_logs_entity (entity_type, entity_id), KEY idx_audit_logs_user_created (user_id, created_at), CONSTRAINT fk_audit_logs_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
